            class Meta:
                formfield_callback = lambda f: fields.IntegerField()

        form = BaseFormWithCallback
        self.assertTrue(hasattr(form, 'formfield_callback'))

    def test_base_formfield_callback_is_not_used_if_not_present(self):
        class BaseForm(BaseModelForm):
            pass

        form = BaseForm
        self.assertFalse(hasattr(form, 'formfield_callback'))

    def test_bases_is_basemodelform(self):
        class MyForm(BaseModelForm):
            pass

        form = MyForm
        self.assertEqual(MyForm.__new__, BaseModelForm.__new__)

    def test_bases_is_not_basemodelform(self):
        class MyForm(BaseModelForm):
            class Meta:
                pass

        form = MyForm
        self.assertEqual(MyForm.__new__, BaseModelForm.__new__)
