from unittest import TestCase
from django.test import SimpleTestCase
from django.http import HttpRequest
from django.utils.functional import wraps

from . import _multi_decorate

class MultiDecorateTest(TestCase):

    def test_multi_decorate_iterable(self):
        def dec1(func):
            def wrapper(*args, **kwargs):
                return "dec1:" + func(*args, **kwargs)
            return wraps(func)(wrapper)

        def dec2(func):
            def wrapper(*args, **kwargs):
                return "dec2:" + func(*args, **kwargs)
            return wraps(func)(wrapper)

        def my_func(*args, **kwargs):
            return "original"

        decorated_func = _multi_decorate([dec1, dec2], my_func)
        self.assertEqual(decorated_func(), "dec2:dec1:original")

    def test_multi_decorate_single(self):
        def dec(func):
            def wrapper(*args, **kwargs):
                return "dec:" + func(*args, **kwargs)
            return wraps(func)(wrapper)

        def my_func(*args, **kwargs):
            return "original"

        decorated_func = _multi_decorate(dec, my_func)
        self.assertEqual(decorated_func(), "dec:original")

    def test_multi_decorate_no_decorators(self):
        def my_func(*args, **kwargs):
            return "original"

        decorated_func = _multi_decorate(None, my_func)
        self.assertEqual(decorated_func(), "original")

    def test_update_wrapper(self):
        def dec(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        def my_func(*args, **kwargs):
            return "original"

        decorated_func = _multi_decorate(dec, my_func)
        self.assertEqual(decorated_func.__name__, my_func.__name__)
        self.assertEqual(decorated_func.__doc__, my_func.__doc__)
        self.assertEqual(decorated_func(), "original")
