import pytest
from _pytest.pytester import Pytester

def test_collect_empty_dict(pytester: Pytester) -> None:
    """Test that collect returns an empty list when the object has an empty __dict__."""
    class EmptyDictClass:
        pass

    item = pytester.getitem(EmptyDictClass)
    assert not item.listcollected()

def test_collect_with_ignored_attribute(pytester: Pytester) -> None:
    """Test that collect skips attributes in __dict__ that are in IGNORED_ATTRIBUTES."""
    class TestClass:
        def __init__(self):
            self.ignored_attr = 1
            self.test_attr = 2

    item = pytester.getitem(TestClass)
    collected_items = item.listcollected()
    assert len(collected_items) == 1
    assert collected_items[0].name == "test_attr"

def test_collect_with_multiple_attributes(pytester: Pytester) -> None:
    """Test that collect returns all attributes in __dict__ that are not ignored."""
    class TestClass:
        def __init__(self):
            self.attr1 = 1
            self.attr2 = 2
            self.attr3 = 3

    item = pytester.getitem(TestClass)
    collected_items = item.listcollected()
    assert len(collected_items) == 3
    assert [item.name for item in collected_items] == ["attr1", "attr2", "attr3"]

def test_collect_with_base_class_attributes(pytester: Pytester) -> None:
    """Test that collect includes attributes from base classes."""
    class BaseClass:
        def __init__(self):
            self.base_attr = 1

    class DerivedClass(BaseClass):
        def __init__(self):
            super().__init__()
            self.derived_attr = 2

    item = pytester.getitem(DerivedClass)
    collected_items = item.listcollected()
    assert len(collected_items) == 2
    assert [item.name for item in collected_items] == ["base_attr", "derived_attr"]

def test_collect_with_ignored_attribute_in_base_class(pytester: Pytester) -> None:
