from django.test import TestCase
from unittest import mock
from django.db import models

class ModelInitTests(TestCase):

    def test_abstract_model_instantiation(self):
        class AbstractModel(models.Model):
            pass

        with self.assertRaises(TypeError):
            AbstractModel()

    def test_model_init_with_args_exceeding_fields(self):
        class Model(models.Model):
            field1 = models.CharField(max_length=255)
            field2 = models.IntegerField()

        with self.assertRaises(IndexError):
            Model("value1", "value2", "extra_value")

    def test_model_init_with_kwargs_and_args(self):
        class Model(models.Model):
            field1 = models.CharField(max_length=255)
            field2 = models.IntegerField()

        model_instance = Model(field1="value1", field2=2)
        self.assertEqual(model_instance.field1, "value1")
        self.assertEqual(model_instance.field2, 2)

    def test_model_init_with_deferred_field(self):
        class Model(models.Model):
            field1 = models.CharField(max_length=255)
            field2 = models.IntegerField()

        model_instance = Model(field1=None)
        self.assertIsNone(model_instance.field1)
        self.assertIsNone(model_instance.field2)

    def test_model_init_with_related_field(self):
        class RelatedModel(models.Model):
            pass

        class Model(models.Model):
            related_field = models.ForeignKey(RelatedModel, on_delete=models.CASCADE)

        related_instance = RelatedModel()
        model_instance = Model(related_field=related_instance)
        self.assertEqual(model_instance.related_field, related_instance)

    def test_model_init_with_related_field_and_kwargs(self):
        class RelatedModel(models.Model):
            pass

        class Model(models.Model):
            related_field = models.ForeignKey(RelatedModel, on_delete=models.CASCADE)
            field1 = models.CharField(max_length=255)

        related_instance = RelatedModel()
        model_instance = Model(related_field=related_instance, field1="value1")
        self.assertEqual(model_instance.related_field, related_instance)
        self.assertEqual(model_instance.field1, "value1")

    def test_model_init_with_no_kwargs_and_no_args(self):
        class Model(models.Model):
            field1 = models.CharField(max_length=255)
            field2 = models.IntegerField()

        model_instance = Model()
        self.assertIsNone(model_instance.field1)
        self.assertIsNone(model_instance.field2)
