from django.conf import settings
from django.test import TestCase
from django.db import models

class Model(models.Model):
    pass

class ModelWithBigAutoField(models.Model):
    id = models.BigAutoField(primary_key=True)
    class Meta:
        app_label = 'test_app'

class ModelWithAutoField(models.Model):
    class Meta:
        app_label = 'test_app'

class TestModelChecks(TestCase):
    def test_default_pk_warning(self):
        # Path 1: cls._meta.pk.auto_created is True and DEFAULT_AUTO_FIELD is not overridden
        settings.DEFAULT_AUTO_FIELD = 'django.db.models.AutoField'
        errors = Model._check_default_pk()
        self.assertEqual(len(errors), 1)
        self.assertEqual(errors[0].id, 'models.W042')

    def test_no_warning_explicit_pk(self):
        # Path 2: cls._meta.pk.auto_created is False
        settings.DEFAULT_AUTO_FIELD = 'django.db.models.BigAutoField'
        ModelWithBigAutoField.Meta.app_label = 'test_app'
        errors = ModelWithBigAutoField._check_default_pk()
        self.assertEqual(len(errors), 0)

    def test_no_warning_explicit_pk_inherited(self):
        class Parent(models.Model):
            id = models.BigAutoField(primary_key=True)

        class Child(Parent):
            pass

        settings.DEFAULT_AUTO_FIELD = 'django.db.models.AutoField'
        errors = Child._check_default_pk()
        self.assertEqual(len(errors), 0)

    def test_no_warning_default_auto_field_overridden(self):
        # Path 2: settings.DEFAULT_AUTO_FIELD is overridden
        settings.DEFAULT_AUTO_FIELD = 'django.db.models.BigAutoField'
        errors = Model._check_default_pk()
        self.assertEqual(len(errors), 0)
