from django.test import TestCase
from django.core.checks import Error
from django.apps import apps

class ModelCheckSwappableTests(TestCase):

    def test_swapped_model_exists(self):
        class Model1(models.Model):
            class Meta:
                swapped = 'check_framework.Model2'

        class Model2(models.Model):
            pass

        self.assertEqual(Model1._meta.swapped, 'check_framework.Model2')
        errors = []
        try:
            apps.get_model('check_framework.Model2')
        except LookupError:
            errors.append(Error(
                "'check_framework.Model2' references '%s.%s', which has not been installed, or is abstract." %
                ('check_framework.Model2', 'Model2'), id='models.E002'))
        self.assertEqual(errors, [])

    def test_swapped_model_not_exists(self):
        class Model1(models.Model):
            class Meta:
                swapped = 'check_framework.NonExistentModel'

        errors = []
        try:
            apps.get_model('check_framework.NonExistentModel')
        except LookupError:
            errors.append(Error(
                "'check_framework.NonExistentModel' references '%s.%s', which has not been installed, or is abstract." %
                ('check_framework.NonExistentModel', 'NonExistentModel'), id='models.E002'))
        self.assertEqual(errors, [])

    def test_swapped_model_invalid_format(self):
        class Model1(models.Model):
            class Meta:
                swapped = 'invalid_format'

        errors = []
        try:
            apps.get_model('invalid_format')
        except ValueError:
            errors.append(Error(
                "'invalid_format' is not of the form 'app_label.app_name'.", id='models.E001'))
        self.assertEqual(errors, [])

    def test_no_swapped_model(self):
        class Model1(models.Model):
            class Meta:
                pass

        self.assertEqual(Model1._meta.swapped, None)
        errors = []
        self.assertEqual(errors, [])
