from django.test import TestCase
from django.db import models

class Model:
    class Meta:
        abstract = True

class TestM2MThroughSameRelationship(TestCase):

    def test_m2m_through_same_relationship_collision(self):
        class Model1(Model):
            class Meta:
                pass

        class Model2(Model):
            class Meta:
                pass

        # Create two M2M fields through the same intermediate model
        class IntermediateModel(Model):
            pass

        model1_field1 = models.ManyToManyField(IntermediateModel, through=models.ManyToOneRel())
        model1_field2 = models.ManyToManyField(IntermediateModel, through=models.ManyToOneRel())

        Model1._meta.local_many_to_many = [model1_field1, model1_field2]

        errors = Model1._check_m2m_through_same_relationship()
        self.assertTrue(len(errors) == 1)
        self.assertEqual(errors[0].id, 'models.E003')

    def test_m2m_through_different_relationship(self):
        class Model1(Model):
            class Meta:
                pass

        class Model2(Model):
            class Meta:
                pass

        # Create two M2M fields through different intermediate models
        class IntermediateModel1(Model):
            pass

        class IntermediateModel2(Model):
            pass

        model1_field1 = models.ManyToManyField(IntermediateModel1, through=models.ManyToOneRel())
        model1_field2 = models.ManyToManyField(IntermediateModel2, through=models.ManyToOneRel())

        Model1._meta.local_many_to_many = [model1_field1, model1_field2]

        errors = Model1._check_m2m_through_same_relationship()
        self.assertEqual(len(errors), 0)

    def test_no_m2m_fields(self):
        class Model(Model):
            class Meta:
                pass

        errors = Model._check_m2m_through_same_relationship()
        self.assertEqual(len(errors), 0)

    def test_m2m_through_non_model(self):
        class Model(Model):
            class Meta:
                pass

        # Create a M2M field through a non-model
        model_field = models.ManyToManyField('self', through=models.ManyToOneRel())

        Model._meta.local_many_to_many = [model_field]

        errors = Model._check_m2m_through_same_relationship()
        self.assertEqual(len(errors), 0)
